package org.slavicmyths.morozko;
import java.util.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.phys.*;
import net.minecraft.world.item.*;
public final class FrostSkills {
 public static long now(ServerPlayer p){return p.server.overworld().getGameTime();}
 public static net.minecraft.nbt.CompoundTag data(ServerPlayer p){return FrostLedger.get(p.serverLevel()).player(p.getUUID());}
 private static boolean pay(ServerPlayer p,String key,int cd){var n=data(p);if(now(p)<n.getLong(key))return false;n.putLong(key,now(p)+cd);FrostLedger.get(p.serverLevel()).setDirty();return true;}
 public static void action(ServerPlayer p,int a){if(!p.isAlive()||p.isSpectator()||a<0||a>5)return;var ephemeral=p.getPersistentData();if(a==4){if(p.isUsingItem()&&p.getUseItem().is(FrostContent.STAFF.get()))ephemeral.putLong("FrostStreamHeartbeat",now(p));return;}if(a==5){if(ephemeral.getBoolean("FrostStreaming")){stopStream(p,"stream_released");if(p.isUsingItem()&&p.getUseItem().is(FrostContent.STAFF.get()))p.stopUsingItem();}return;}if(now(p)<ephemeral.getLong("FrostActionReady"))return;ephemeral.putLong("FrostActionReady",now(p)+3);if(a==3){mirror(p);return;}if(!p.getMainHandItem().is(FrostContent.STAFF.get())||p.containerMenu!=p.inventoryMenu)return;if(a==0)shoot(p);else if(a==1)icicles(p);else if(a==2&&pay(p,"WaveReady",FrostRules.WAVE_CD)){p.swing(net.minecraft.world.InteractionHand.MAIN_HAND,true);pose(p,7);FrostHazard.playerWave(p);FrostContent.sound(p,"staff_wave");}}
 public static void shoot(ServerPlayer p){if(p.getAttackStrengthScale(0)<.9f||!pay(p,"BoltReady",16))return;p.resetAttackStrengthTicker();p.swing(net.minecraft.world.InteractionHand.MAIN_HAND,true);FrostShard.launch(p,p.getEyePosition().add(p.getLookAngle().scale(20)),org.slavicmyths.combat.RewardWeaponBalance.FROST_BOLT,8,null);FrostContent.sound(p,"staff_shoot");}
 public static boolean startStream(ServerPlayer p){
  if(!p.isAlive()||p.isSpectator()||p.containerMenu!=p.inventoryMenu)return false;
  var state=p.getPersistentData();long time=now(p),ready=data(p).getLong("StreamReady");
  if(time<ready){if(time>=state.getLong("FrostStreamNoticeReady")){p.displayClientMessage(FrostContent.text("stream_cooldown",(ready-time+19)/20),true);state.putLong("FrostStreamNoticeReady",time+20);}return false;}
  if(state.getBoolean("FrostStreaming"))return p.isUsingItem()&&p.getUseItem().is(FrostContent.STAFF.get());
  state.remove("FrostStaffPose");state.putLong("FrostStreamHeartbeat",time);state.putLong("FrostStreamUntil",time+FrostRules.STREAM_DURATION);state.putBoolean("FrostStreaming",true);
  net.neoforged.neoforge.network.PacketDistributor.sendToPlayersTrackingEntityAndSelf(p,new FrostNetwork.Stream(p.getId()));FrostNetwork.send(p);return true;
 }
 public static void streamTick(ServerPlayer p,int remaining){
  var state=p.getPersistentData();long time=now(p);
  String reason=!state.getBoolean("FrostStreaming")?null:!p.isAlive()||p.isSpectator()?"stream_released":p.containerMenu!=p.inventoryMenu?"stream_menu":time>=state.getLong("FrostStreamUntil")?"stream_finished":time-state.getLong("FrostStreamHeartbeat")>FrostRules.STREAM_HEARTBEAT_GRACE?"stream_connection":null;
  if(!state.getBoolean("FrostStreaming")||reason!=null){if(reason!=null)stopStream(p,reason);p.stopUsingItem();return;}
  int age=(int)(FrostRules.STREAM_DURATION-(state.getLong("FrostStreamUntil")-time));
  if(age<4)return;if(age%10==4){for(var t:p.serverLevel().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(10),t->FrostWorld.hostile(t,p)&&FrostWorld.cone(p,t,10,12.5))){if(t.hurt(org.slavicmyths.combat.MythDamageSources.caused("morozko_stream",p),org.slavicmyths.combat.RewardWeaponBalance.FROST_PULSE)){FrostCold.add(t,6);remember(p,t);}}}if(age%3==0)FrostVisuals.cone(p.serverLevel(),p,10);
 }
 public static void stopStream(ServerPlayer p){stopStream(p,null);}
 public static void stopStream(ServerPlayer p,String reason){if(p.getPersistentData().getBoolean("FrostStreaming")){var state=p.getPersistentData();state.remove("FrostStreaming");state.remove("FrostStreamUntil");state.remove("FrostStreamHeartbeat");data(p).putLong("StreamReady",now(p)+FrostRules.STREAM_CD);FrostLedger.get(p.serverLevel()).setDirty();if(reason!=null)p.displayClientMessage(FrostContent.text(reason),true);FrostNetwork.send(p);}}
 public static void remember(ServerPlayer p,LivingEntity e){var n=p.getPersistentData();n.putUUID("FrostLastTarget",e.getUUID());n.putLong("FrostLastHit",now(p));}
 private static void icicles(ServerPlayer p){var n=p.getPersistentData();var t=n.hasUUID("FrostLastTarget")?p.serverLevel().getEntity(n.getUUID("FrostLastTarget")):null;if(!(t instanceof LivingEntity e)||!e.isAlive()||p.distanceToSqr(e)>324||now(p)-n.getLong("FrostLastHit")>160||!p.hasLineOfSight(e)||!FrostWorld.hostile(e,p)){p.displayClientMessage(FrostContent.text("no_target"),true);return;}if(now(p)<data(p).getLong("IcicleReady"))return;var positions=new ArrayList<Vec3>();var at=e.getBoundingBox().getCenter();double[][] offsets={{-.6,0},{.6,0},{0,-.6},{0,.6},{0,0}};for(var o:offsets){Vec3 bottom=new Vec3(at.x+o[0],e.getY(),at.z+o[1]);Vec3 top=bottom.add(0,e.getBbHeight()+5,0);var hit=p.serverLevel().clip(new net.minecraft.world.level.ClipContext(bottom.add(0,e.getBbHeight()+.1,0),top,net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,p));if(hit.getType()!=HitResult.Type.MISS)top=hit.getLocation().add(0,-2.5,0);if(top.y<bottom.y+e.getBbHeight()+1.8||!p.serverLevel().noCollision(new AABB(top.x-.3,top.y,top.z-.3,top.x+.3,top.y+2.4,top.z+.3))){p.displayClientMessage(FrostContent.text("space"),true);return;}positions.add(top);}if(!pay(p,"IcicleReady",FrostRules.ICICLE_CD))return;for(int i=0;i<5;i++)FrostHazard.falling(p,positions.get(i),16+i*3,e.getY());pose(p,16);p.swing(net.minecraft.world.InteractionHand.MAIN_HAND,true);FrostContent.sound(p,"spike_telegraph");}
 private static void pose(ServerPlayer p,int duration){p.getPersistentData().putLong("FrostStaffPose",now(p)+duration);p.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);}
 public static PlayerDouble copy(ServerPlayer p){return p.serverLevel().getEntitiesOfClass(PlayerDouble.class,p.getBoundingBox().inflate(64),c->p.getUUID().equals(c.owner())&&c.isAlive()).stream().findFirst().orElse(null);}
 public static void mirror(ServerPlayer p){if(org.slavicmyths.item.FolkAccessoryItem.equipped(p,FrostContent.MIRROR.get()).isEmpty()||copy(p)!=null||now(p)<data(p).getLong("MirrorReady"))return;var side=new Vec3(Math.cos(Math.toRadians(p.getYRot()))*2,0,Math.sin(Math.toRadians(p.getYRot()))*2);var at=FrostWorld.safe(p.serverLevel(),p.position().add(side),.6f,1.8f,1);if(at==null)at=FrostWorld.safe(p.serverLevel(),p.position().subtract(side),.6f,1.8f,3);if(at==null){p.displayClientMessage(FrostContent.text("space"),true);return;}var c=FrostContent.MIRROR_ENTITY.get().create(p.serverLevel());if(c==null)return;c.configure(p);c.setPos(at);p.serverLevel().addFreshEntity(c);pay(p,"MirrorReady",FrostRules.MIRROR_CD);FrostContent.sound(p,"mirror_summon");FrostVisuals.ring(p.serverLevel(),p.position(),1.8,.2,18);}
 public static boolean unlock(ServerPlayer p,Entity npc){if(!p.isAlive()||p.isSpectator()||p.distanceToSqr(npc)>64||!p.hasLineOfSight(npc))return false;boolean eligible=npc instanceof org.slavicmyths.yaga.BabaYaga&&org.slavicmyths.quest185.Quest185Story.yagaTrust(p)>=2||npc instanceof org.slavicmyths.bayun.BayunEntity b&&b.bond(p).getBoolean("FirstGift");if(!eligible){p.displayClientMessage(FrostContent.text("trust"),true);return false;}var n=data(p);if(n.getBoolean("Unlocked")){if(org.slavicmyths.rpg.Runes.inventoryCount(p,FrostContent.TOTEM.get())==0&&n.getList("Pending",10).isEmpty())FrostLedger.get(p.serverLevel()).enqueue(p,new ItemStack(FrostContent.TOTEM.get()));}else{if(org.slavicmyths.rpg.Runes.inventoryCount(p,Items.SNOW_BLOCK)<8||org.slavicmyths.rpg.Runes.inventoryCount(p,Items.BLUE_ICE)<1){p.displayClientMessage(FrostContent.text("offering"),true);return false;}org.slavicmyths.quest185.Quest185Story.spend(p,Items.SNOW_BLOCK,8);org.slavicmyths.quest185.Quest185Story.spend(p,Items.BLUE_ICE,1);n.putBoolean("Unlocked",true);FrostLedger.get(p.serverLevel()).enqueue(p,new ItemStack(FrostContent.TOTEM.get()));}FrostLedger.get(p.serverLevel()).setDirty();FrostLedger.get(p.serverLevel()).collect(p);org.slavicmyths.tales.TaleService.promote(p,"slavicmyths:morozko_trial",2,false);p.sendSystemMessage(FrostContent.text("totem_given"));return true;}
 private FrostSkills(){}
}
